  assert.equal(b.selectedText(), 'world');
  assert.equal(b.cursor, 11);
  b.select(11, 6);
  assert.deepEqual(b.selection, { from: 6, to: 11 });
  assert.equal(b.cursor, 6);
  b.select(3, 3);
  assert.equal(b.selection, null);
  assert.equal(b.cursor, 3);
