  assert.equal(b.text().length, 30 - 1);
  assert.equal(b.cursor, 30 - 1);
  b.insert('b');
  assert.equal(b.text().length, 30);
  assert.throws(() => b.insert('c'), RangeError);
  assert.equal(b.cursor, 30);
