test('silent operations', () => {
  const b = new Buffer('abc');
  let calls = 0;
  b.onChange(() => { calls += 1; });
  b.insert('');
  b.delete(0);
  b.backspace(0);
  b.delete(3);
  b.moveTo(0);
  b.moveBy(2);
  b.backspace(0);
  assert.equal(calls, 0);
  b.delete(5);
  assert.equal(calls, 1);
  b.backspace(5);
  assert.equal(calls, 2);
  assert.equal(b.text(), '');
  for (const bad of [null, 'x', 5]) assert.throws(() => b.onChange(bad), TypeError);
