  b.select(0, 5);
  b.moveTo(2);
  assert.equal(b.selection, null);
  b.select(0, 5);
  b.moveBy(1);
  assert.equal(b.selection, null);
  b.select(0, 5);
  b.moveBy(0);
  assert.equal(b.selection, null);
  b.select(0, 5);
  b.insert('');
