  b.moveTo(3);
  assert.equal(b.backspace(2), 'el');
  assert.equal(b.cursor, 1);
  b.undo();
  assert.equal([b.text(), b.cursor].join('|'), 'hello|3');
  b.redo();
  assert.equal([b.text(), b.cursor].join('|'), 'hlo|1');
});

