  }

  redo() {
    const rec = this._redo.pop();
    if (!rec) return false;
    this._replaying = true;
    try {
      this._replace(rec.start, rec.start + rec.removed.length, rec.inserted, rec.cursorAfter);
    } finally {
      this._replaying = false;
    }
    this._undo.push(rec);
    return true;
  }
}

